// Group tweets by 'Narratives'
const groupedByNarratives = {};
for (const item of $input.all()) {
  const narrative = item.json.Narrative;
  if (!groupedByNarratives[narrative]) {
    groupedByNarratives[narrative] = [];
  }
  groupedByNarratives[narrative].push(item.json);
}

// Randomize within each Narrative's tweets
const results = [];
for (const [narrative, tweets] of Object.entries(groupedByNarratives)) {

  // 1. Shuffle tweets for this narrative
  const shuffled = tweets.sort(() => Math.random() - 0.5);

  // 2. Calculate Midpoint with randomization for odd numbers
  // If length is even (e.g. 10), floor and ceil are the same (5).
  // If length is odd (e.g. 11), we randomly choose between 5 and 6.
  const useCeil = Math.random() < 0.5;
  const midpoint = useCeil 
    ? Math.ceil(shuffled.length / 2) 
    : Math.floor(shuffled.length / 2);

  // 3. Assign Control group (0 to midpoint)
  for (let i = 0; i < midpoint; i++) {
    results.push({
      ...shuffled[i],
      group: 'Control'
    });
  }

  // 4. Assign Treatment group (midpoint to end)
  for (let i = midpoint; i < shuffled.length; i++) {
    results.push({
      ...shuffled[i],
      group: 'Treatment'
    });
  }
}

return results.map(item => ({ json: item }));

// Define the available KPIs
const globalKpis = ['Persuasiveness', 'Emotional Engagement', 'Shareability'];

// Group items by narrative
const groupedByNarrative = {};
for (const item of $input.all()) {
  const narrative = item.json.Narrative;
  if (!groupedByNarrative[narrative]) {
    groupedByNarrative[narrative] = [];
  }
  groupedByNarrative[narrative].push(item.json);
}

const results = [];

// Assign KPIs within each narrative's tweets
for (const [narrative, tweets] of Object.entries(groupedByNarrative)) {
  const tweetCount = tweets.length;

  // 1. Create a specific shuffled order of KPIs for THIS narrative.
  // This ensures that if there is a remainder, the "lucky" KPI that gets 
  // the extra slot is chosen randomly, not based on the fixed global order.
  const narrativeKpis = [...globalKpis].sort(() => Math.random() - 0.5);

  // Create balanced KPI assignment for this author
  const assignments = [];
  const itemsPerKPI = Math.floor(tweetCount / narrativeKpis.length);
  const remainder = tweetCount % narrativeKpis.length;

  for (let i = 0; i < narrativeKpis.length; i++) {
    // The first few KPIs in our shuffled list get the extra item
    const count = itemsPerKPI + (i < remainder ? 1 : 0);
    for (let j = 0; j < count; j++) {
      assignments.push(narrativeKpis[i]);
    }
  }

  // 2. Shuffle the final assignments list
  // (This mixes the order so the "Persuasiveness" tweets aren't all at the top)
  for (let i = assignments.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [assignments[i], assignments[j]] = [assignments[j], assignments[i]];
  }

  // Apply assignments to tweets
  tweets.forEach((tweet, index) => {
    results.push({
      json: {
        ...tweet,
        assigned_kpi: assignments[index],
        // Note: This calculates the distribution for this specific batch
        narrative_kpi_distribution: assignments.reduce((acc, kpi) => {
          acc[kpi] = (acc[kpi] || 0) + 1;
          return acc;
        }, {})
      }
    });
  });
}

return results;

