for (const inputItem of $input.all()) {
  // Get the claim text from the input item
  // Adjust the property name based on your actual data structure
  const claimText = inputItem.json.Narrative

  // Find exact match
  let claimNumber = claimsMapping[claimText];

  // If no exact match found, try fuzzy matching
  if (!claimNumber) {
    // Look for partial matches or close matches
    const claimKeys = Object.keys(claimsMapping);

    for (const key of claimKeys) {
      // Check if the input contains the key or vice versa
      if (claimText.includes(key) || key.includes(claimText)) {
        claimNumber = claimsMapping[key];
        break;
      }
    }

    // If still no match, try case-insensitive comparison
    if (!claimNumber) {
      const lowerClaim = claimText.toLowerCase();
      for (const key of claimKeys) {
        if (key.toLowerCase() === lowerClaim) {
          claimNumber = claimsMapping[key];
          break;
        }
      }
    }
  }

  // Create output item by copying all original data and adding claim number
  outputItems.push({
    json: {
      ...inputItem.json,  // Preserve all original data
      claimNumber: claimNumber || null
    }
  });
}

return outputItems;

