function formatTimestamp(timestamp) {
  if (!timestamp) return null;
  const date = new Date(timestamp);
  return date.toLocaleString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  });
}

function getBestNarrativeResult(results, assetName) {
  // 1. Safety check: if no results, return null
  if (!results || results.length === 0) return null;

  // 2. If only one result exists, return it immediately
  if (results.length === 1) return results[0];

  // 3. If we have multiple results and an Asset name, try to match keywords
  if (assetName) {
    const normalizedAsset = assetName.toString().toLowerCase();

    // Iterate through the available narrative results
    const match = results.find(result => {
      // IMPORTANT: This key must match the keys in NARRATIVE_RULES
      const key = result.key; 
      const keywords = NARRATIVE_RULES[key] || []; 

      // Check if the Asset string contains any of the keywords
      return keywords.some(keyword => normalizedAsset.includes(keyword.toLowerCase()));
    });

    // If a match is found, return it
    if (match) return match;
  }

  // 4. Fallback: If no specific match is found, return the first one
  return results[0];
}

