const LAMBDA_MATRIX = {
  "Tier 1": { "Low": 0.5, "Mid": 1.0, "High": 1.5 },
  "Tier 2": { "Low": 1.0, "Mid": 1.5, "High": 2.0 },
  "Tier 3": { "Low": 1.5, "Mid": 2.0, "High": 3.0 },
  "Tier 4": { "Low": 2.0, "Mid": 3.0, "High": 4.0 }
};

// ---------------------------------------------------------
// HELPER: Poisson Sampler
// ---------------------------------------------------------
function getPoisson(lambda) {
  const L = Math.exp(-lambda);
  let p = 1.0;
  let k = 0;

  do {
    k++;
    p *= Math.random();
  } while (p > L);

  return k - 1;
}

// ---------------------------------------------------------
// HELPER: Determine Author Tier
// ---------------------------------------------------------
function getTier(followers) {
  if (!followers) return "Tier 1"; 
  const f = parseInt(followers, 10);
  if (f >= 10000) return "Tier 4";
  if (f >= 1000) return "Tier 3";
  if (f >= 500) return "Tier 2";
  return "Tier 1";
}

