const results = [];

for (const item of $input.all()) {
  const tweet = item.json;

  // Initialize variables
  let k;
  let lambda = null;
  let category = null;
  let tier = null;

  // --- LOGIC CHANGE START ---
  // Check if it is a comment (case-insensitive check)
  const isComment = tweet.Type && tweet.Type.toLowerCase() === 'comment';

  if (isComment) {
      // If comment, force 1 reply
      k = 1;
  } else {
      // If post (or unknown), run standard Poisson logic
      category = NARRATIVE_CATEGORIES[tweet.Narrative] || "Mid";
      tier = getTier(tweet.Author_Followers);
      lambda = LAMBDA_MATRIX[tier][category];
      k = getPoisson(lambda);

      // Apply Clamping (Min 1, Max 5)
      k = Math.max(1, Math.min(5, k));
  }
  // --- LOGIC CHANGE END ---

  const finalUserPrompt = `CLAIM TO COUNTER:\n"${tweet.Tweet_Text}"`;

  results.push({
    json: {
      ...tweet,
      target_response_count: k,
      Final_User_Prompt: finalUserPrompt,
      sampling_metadata: {
        is_comment: isComment,
        original_lambda: lambda, // Will be null if comment
        narrative_category: category,
        author_tier: tier,
        total_replies_requested: k
      }
    }
  });
}

return results;

