      ...json, // Copy all original metadata (User, Stats, etc.) from the first item
      collected_cns: []
    };
  }

  // 3. Collect the generated CN text
  if (json.Generated_CN) {
    groups[url].collected_cns.push(json.Generated_CN);
  }
}

// 4. Transform back to a clean list
const results = Object.values(groups).map(group => {
  // Format the CNs into a single string:
  // "1. [First CN]
  //  2. [Second CN]"
  const formattedCNs = group.collected_cns
    .map((cn, i) => `${i + 1}. ${cn}`)
    .join('\n\n');

  return {
    json: {
      ...group,
      "CN(s)": formattedCNs,        // The new combined text field
      "Num_of_CNs": group.collected_cns.length // The count
    }
  };
});

return results;

// 1. Get the original Source Data (Tweet + Prompt)
// Because of 'Merge by Position', Source[0] matches AgentResponse[0]
const sourceItems = $('Merge').all();

// 2. Get the Raw Agent Output
const agentItems = $input.all();

// 3. Filter: Keep only the "Main" Agent responses (Index 0 or undefined)
// This removes the redundant 'Index 1', 'Index 2' items that n8n/Gemini creates.
const mainAgentResponses = agentItems.filter(item => {
    const json = item.json;
    return json.index === undefined || json.index === 0;
});

const results = [];

// 4. Loop through the cleaned list
for (let i = 0; i < mainAgentResponses.length; i++) {

    // Safety check: Ensure we have a matching source item
    if (i >= sourceItems.length) break;

    const sourceData = sourceItems[i].json;
    const agentData = mainAgentResponses[i].json;

    // 5. Extract Candidates from the 'parts' array
    // This array contains all the k variations generated for this specific tweet
    const parts = agentData.content?.parts || [];

    if (parts.length > 0) {
        parts.forEach((part, partIndex) => {
            if (part.text) {
                results.push({
                    json: {
                        ...sourceData,       // Restore URL, User, Metrics
                        Generated_CN: part.text, // The specific CN text
                        cn_index: partIndex + 1
                    }
                });
            }
        });
    } 
    // Fallback: If Gemini returned a single string instead of parts
    else {
        const simpleText = agentData.text || agentData.output;
        if (simpleText) {
            results.push({
                json: {
                    ...sourceData,
                    Generated_CN: simpleText,
                    cn_index: 1
                }
            });
        }
    }
}

return results;

